    val root: JsonObject = Json.parseToJsonElement(INPUTS).jsonObject
    fun objectAt(name: String): JsonObject = root.getValue(name).jsonObject
    fun text(group: String, key: String): String = objectAt(group).getValue(key).jsonPrimitive.content
    fun nestedText(group: String, entry: String, key: String): String =
        objectAt(group).getValue(entry).jsonObject.getValue(key).jsonPrimitive.content
    val baseDetails: JsonObject = objectAt("draftMetadataInputFragment").getValue("deliveryDetails").jsonObject
    val metadataVariants: List<JsonObject> = root.getValue("deliveryMetadataVariants").jsonArray.map { it.jsonObject }
    val conditionalVariants: List<JsonObject> = root.getValue("conditionalMetadataVariants").jsonArray.map { it.jsonObject }
    val ownCheckVariants: List<JsonObject> = root.getValue("ownCheckMetadataVariants").jsonArray.map { it.jsonObject }
    val canonicalDraft: String = text("draftCommandBinding", "canonicalPayloadJson")
    val neutralDraft: String = text("draftCommandBinding", "neutralReferenceCanonicalPayloadJson")
    val canonicalAdd: String = text("draftCommandBinding", "guardedAddCanonicalPayloadJson")
    val canonicalSelector: String = text("diagnostics", "canonicalWholeCheckSelectorJson")
    val canonicalObservation: String = text("diagnostics", "expectedCanonicalDeliveryObservationJson")

    /** Null and absent command objects are distinct raw attempts, not successful DTO values. */
    fun rawDraft(variant: JsonObject): String {
        val prefix = canonicalDraft.substringBefore(",\"deliveryDetails\":")
        val presence = variant["metadataPresence"]?.jsonPrimitive?.content
        if (presence == "ABSENT") return prefix + "}}"
        if (presence == "EXPLICIT_NULL") return prefix + ",\"deliveryDetails\":null}}"
        val details = variant.getValue("deliveryDetails").jsonObject
        val replacement = variant["replaceField"]?.jsonPrimitive?.content
        val rawToken = variant["exactRawJsonStringToken"]?.jsonPrimitive?.content
        val rawDetails = details.entries.joinToString(",", "{", "}") { (key, value) ->
            JsonPrimitive(key).toString() + ":" + if (key == replacement) requireNotNull(rawToken) else value.toString()
        }
        return prefix + ",\"deliveryDetails\":" + rawDetails + "}}"
    }

    /** Form input spelling of the attempted raw token; no invalid value is stored as valid data. */
    fun attemptedFields(variant: JsonObject): Map<String, String> {
        val details = variant["deliveryDetails"] as? JsonObject ?: return emptyMap()
        val result = details.mapValues { (_, value) -> value.jsonPrimitive.content }.toMutableMap()
        val replacement = variant["replaceField"]?.jsonPrimitive?.content
        if (replacement != null) result[replacement] = when (variant.getValue("exactRawJsonStringToken").jsonPrimitive.content) {
            "\"\\ud800\"" -> "\uD800"
            "\"\\udc00\"" -> "\uDC00"
            else -> error("Unspecified frozen raw Unicode token")
        }
        return result
    }

    fun validates(variant: JsonObject): Boolean = variant.getValue("expected").jsonPrimitive.content.startsWith("VALIDATES")
    fun caseId(variant: JsonObject): String = variant.getValue("caseId").jsonPrimitive.content
    fun baseFields(): Map<String, String> = baseDetails.mapValues { (_, value) -> value.jsonPrimitive.content }
    fun prohibitedCodepoints(): List<Int> = objectAt("deliveryMetadataTechnicalRules")
        .getValue("forbiddenAsciiControlCodepoints").jsonArray.map { it.jsonPrimitive.content.removePrefix("U+").toInt(16) }
}
